<script setup lang="ts">defineProps<{steps:{key:string;label:string;count:number;conversionBps:number}[]}>();const fa=(value:number)=>new Intl.NumberFormat("fa-IR").format(value);</script><template><section class="analytics-panel"><header><div><h2>قیف تعامل آگهی</h2><p>نسخه منتشرشده · پنجره تبدیل ۷ روزه</p></div><span class="admin-chip">بدون PII</span></header><ol class="funnel-steps"><li v-for="step in steps" :key="step.key"><div><b>{{step.label}}</b><small>{{fa(step.count)}} کاربر</small></div><span>{{(step.conversionBps/100).toLocaleString('fa-IR')}}٪</span><i :style="{width:`${Math.max(4,step.conversionBps/100)}%`}"/></li></ol></section></template>
